contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint initFlag, uint val) public {
        bool revertedOnce = false;
        uint minSumBefore;

        c.Initialized(); if (__ESBMC_reverted()) return;

        minSumBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedOnce = true;
        } else {
            revertedOnce = false;
        }

        assert(revertedOnce && c.MinSum() == minSumBefore);
    }
}

