pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 initFlag, uint256 val) internal {
        bool revertedOnce = false;
        uint minSumBefore;
        try c.Initialized() {} catch { return; }
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        try c.SetMinSum(val) {
            revertedOnce = false;
        } catch {
            revertedOnce = true;
        }
        assertTrue(revertedOnce && c.MinSum() == minSumBefore);
    }

    function testFuzz_run(uint256 initFlag, uint256 val) public {
        _run(initFlag, val);
    }

    receive() external payable {}
}
